def stopfree_stretches(s):
    res=[]
    for f in range(3):
        i=f; start=f
        while i+3<=len(s):
            cod=s[i:i+3]
            if cod in stops:
                res.append((start,i,i-start)); start=i+3
            i+=3
        res.append((start,len(s)-(len(s)-f)%3, len(s)-(len(s)-f)%3-start))
